use super::*;
fn note(id:&str,body:&str)->NewEntry{NewEntry{workspace_id:id.into(),kind:"note".into(),title:"Research note".into(),body:body.into(),..Default::default()}}
fn publish(s:&Store,mut input:NewEntry)->RefractResult<WorkspaceView>{let p=s.margin_preview(&input)?;input.review_hash=Store::margin_preview_hash(&p)?;s.margin_publish(&input)}
fn transfer(a:&Store,b:&Store,id:&str,kind:&str)->ExchangeResult{let owner=a.margin_view(id).unwrap().owner;let packet=a.margin_export_packet(&ExportRequest{workspace_id:id.into(),recipient:b.margin_contact().unwrap().data.signing_key,kind:kind.into()}).unwrap();b.margin_import_packet(&ImportRequest{packet,expected_owner:owner}).unwrap()}
fn pair(role:&str)->(Store,Store,String){let a=Store::open_in_memory().unwrap();let b=Store::open_in_memory().unwrap();let ws=a.margin_create("Research").unwrap();a.margin_member(&ws.id,&b.margin_contact().unwrap(),role).unwrap();a.margin_enable(&ws.id,true).unwrap();transfer(&a,&b,&ws.id,"invite");b.margin_enable(&ws.id,true).unwrap();(a,b,ws.id)}
#[test]fn private_default_and_selected_recipient_encryption(){let a=Store::open_in_memory().unwrap();let b=Store::open_in_memory().unwrap();let c=Store::open_in_memory().unwrap();let ws=a.margin_create("Research").unwrap();publish(&a,note(&ws.id,"Selected note only")).unwrap();assert!(!ws.exchange_enabled);a.margin_member(&ws.id,&b.margin_contact().unwrap(),"editor").unwrap();let q=ExportRequest{workspace_id:ws.id.clone(),recipient:b.margin_contact().unwrap().data.signing_key,kind:"invite".into()};assert!(a.margin_export_packet(&q).is_err());a.margin_enable(&ws.id,true).unwrap();let packet=a.margin_export_packet(&q).unwrap();assert!(!packet.contains("Selected note only"));assert!(c.margin_inspect(&packet).is_err());assert!(b.margin_import_packet(&ImportRequest{packet:packet.clone(),expected_owner:"wrong".into()}).is_err());assert!(b.margin_list().unwrap().is_empty());let owner=ws.owner;let result=b.margin_import_packet(&ImportRequest{packet,expected_owner:owner}).unwrap();let joined=b.margin_view(&result.workspace_id).unwrap();assert!(!joined.exchange_enabled);assert_eq!(joined.entries[0].versions[0].body,"Selected note only");assert!(b.list_items(100,0).unwrap().is_empty());}
#[test]fn concurrent_versions_converge_without_lww_data_loss(){let(a,b,id)=pair("editor");let ws=publish(&a,note(&id,"base")).unwrap();transfer(&a,&b,&id,"sync");let r=ws.entries[0].versions[0].clone();for(s,text)in[(&a,"owner offline"),(&b,"editor offline")]{s.margin_edit(&EditEntry{workspace_id:id.clone(),entry_id:r.entry_id.clone(),chosen_revision:r.id.clone(),expected_heads:vec![r.id.clone()],title:r.title.clone(),body:text.into(),done:false,deleted:false}).unwrap();}let a_packet=a.margin_export_packet(&ExportRequest{workspace_id:id.clone(),recipient:b.margin_contact().unwrap().data.signing_key,kind:"sync".into()}).unwrap();let b_packet=b.margin_export_packet(&ExportRequest{workspace_id:id.clone(),recipient:a.margin_contact().unwrap().data.signing_key,kind:"sync".into()}).unwrap();let owner=a.margin_view(&id).unwrap().owner;for(s,packet)in[(&a,b_packet),(&b,a_packet)]{s.margin_import_packet(&ImportRequest{packet,expected_owner:owner.clone()}).unwrap();}let av=a.margin_view(&id).unwrap();let bv=b.margin_view(&id).unwrap();assert!(av.entries[0].conflict);assert_eq!(av.entries[0].versions,bv.entries[0].versions);let chosen=&av.entries[0].versions[0];assert!(a.margin_edit(&EditEntry{workspace_id:id.clone(),entry_id:chosen.entry_id.clone(),chosen_revision:chosen.id.clone(),expected_heads:vec![chosen.id.clone()],title:chosen.title.clone(),body:"unreviewed merge".into(),done:false,deleted:false}).is_err());a.margin_edit(&EditEntry{workspace_id:id.clone(),entry_id:chosen.entry_id.clone(),chosen_revision:chosen.id.clone(),expected_heads:av.entries[0].versions.iter().map(|v|v.id.clone()).collect(),title:chosen.title.clone(),body:"explicitly resolved".into(),done:false,deleted:false}).unwrap();transfer(&a,&b,&id,"sync");let result=b.margin_view(&id).unwrap();assert!(!result.entries[0].conflict);assert_eq!(result.entries[0].history_count,4);assert_eq!(result.entries[0].versions[0].body,"explicitly resolved");}
#[test]fn viewer_cannot_write_publish_invite_or_forge_editor_packet(){let(a,b,id)=pair("viewer");assert!(publish(&b,note(&id,"forbidden")).is_err());let q=ExportRequest{workspace_id:id.clone(),recipient:a.margin_contact().unwrap().data.signing_key,kind:"sync".into()};assert!(b.margin_export_packet(&q).is_err());let(p,_,_,_)=b.margin_load(&id).unwrap();let payload=serde_json::json!({"policy":p,"records":[],"acknowledged_hash":null});let me=b.margin_identity_private().unwrap();let packet=secure::seal(&me,&a.margin_contact().unwrap(),&id,p.data.epoch,"sync",&json(&payload).unwrap()).unwrap();assert!(a.margin_import_packet(&ImportRequest{packet,expected_owner:p.data.owner}).is_err());}
#[test]fn policy_revocation_is_enforced_when_learned_and_old_packets_stay_rejected(){let(a,b,id)=pair("editor");publish(&b,note(&id,"old epoch pending")).unwrap();let old=b.margin_export_packet(&ExportRequest{workspace_id:id.clone(),recipient:a.margin_contact().unwrap().data.signing_key,kind:"sync".into()}).unwrap();let owner=a.margin_view(&id).unwrap().owner;a.margin_member(&id,&b.margin_contact().unwrap(),"removed").unwrap();assert!(a.margin_import_packet(&ImportRequest{packet:old,expected_owner:owner}).is_err());transfer(&a,&b,&id,"policy");assert_eq!(b.margin_view(&id).unwrap().role,"removed");assert!(publish(&b,note(&id,"forbidden")).is_err());assert_eq!(b.margin_view(&id).unwrap().entries[0].versions[0].body,"old epoch pending");b.margin_enable(&id,false).unwrap();b.margin_enable(&id,true).unwrap();a.margin_member(&id,&b.margin_contact().unwrap(),"viewer").unwrap();transfer(&a,&b,&id,"policy");assert_eq!(b.margin_view(&id).unwrap().role,"viewer");}
#[test]fn receipts_are_explicit_bound_to_recipient_and_replays_are_idempotent(){let(a,b,id)=pair("viewer");publish(&a,note(&id,"read me")).unwrap();let result=transfer(&a,&b,&id,"sync");assert!(a.margin_view(&id).unwrap().pending_transfers>=1);let receipt=b.margin_receipt(&id,&result.packet_hash).unwrap();let owner=a.margin_view(&id).unwrap().owner;let first=a.margin_import_packet(&ImportRequest{packet:receipt.clone(),expected_owner:owner.clone()}).unwrap();assert!(!first.duplicate);let pretty=serde_json::to_string_pretty(&serde_json::from_str::<secure::Packet>(&receipt).unwrap()).unwrap();assert!(a.margin_import_packet(&ImportRequest{packet:pretty,expected_owner:owner.clone()}).unwrap().duplicate);assert!(a.margin_import_packet(&ImportRequest{packet:receipt,expected_owner:owner}).unwrap().duplicate);let rows=a.margin_transfers(&id).unwrap();assert!(rows.as_array().unwrap().iter().any(|r|r["hash"]==result.packet_hash&&r["acknowledged_ts"].is_i64()));b.margin_enable(&id,false).unwrap();assert!(b.margin_receipt(&id,&result.packet_hash).is_err());}
#[test]fn resilient_anchors_do_not_guess_changed_quotes_or_positions(){use refract_core::{Block,BlockKind};let blocks=vec![Block{idx:0,kind:BlockKind::Heading1,text:"First".into()},Block{idx:1,kind:BlockKind::Paragraph,text:"Before selected quote after.".into()}];let mut a=annotation_engine::build_anchor(&blocks,1,"selected quote").unwrap();a.document_id="doc-a".into();assert_eq!(annotation_engine::resolve_document_anchor(&a,"doc-b",&blocks).0,annotation_engine::AnchorStatus::Lost);let changed=vec![Block{idx:0,kind:BlockKind::Paragraph,text:"Before entirely different after.".into()}];assert_eq!(annotation_engine::resolve_anchor(&a,&changed).0,annotation_engine::AnchorStatus::Lost);let mut duplicate=blocks.clone();duplicate.push(Block{idx:2,kind:BlockKind::Paragraph,text:"Before selected quote after.".into()});a.heading=None;a.prefix.clear();a.suffix.clear();assert_eq!(annotation_engine::resolve_anchor(&a,&duplicate).0,annotation_engine::AnchorStatus::Ambiguous);assert!(annotation_engine::build_anchor(&[Block{idx:0,kind:BlockKind::Paragraph,text:"repeat repeat".into()}],0,"repeat").is_err());}
#[test]fn malformed_import_and_immutable_rewrites_roll_back(){let(a,b,id)=pair("editor");publish(&a,note(&id,"original")).unwrap();transfer(&a,&b,&id,"sync");let(p,doc,_,_)=b.margin_load(&id).unwrap();let mut records=Store::margin_records(&doc).unwrap().into_values().collect::<Vec<_>>();records[0].body="tampered historical content".into();let payload=serde_json::json!({"policy":p,"records":records,"acknowledged_hash":null});let me=b.margin_identity_private().unwrap();let packet=secure::seal(&me,&a.margin_contact().unwrap(),&id,p.data.epoch,"sync",&json(&payload).unwrap()).unwrap();assert!(a.margin_import_packet(&ImportRequest{packet,expected_owner:p.data.owner}).is_err());assert_eq!(a.margin_view(&id).unwrap().entries[0].versions[0].body,"original");assert!(a.margin_inspect("not JSON").is_err());}
fn source(s:&mut Store,id:&str,text:&str){use refract_core::{Item,SourceType,ImportStatus,Block,BlockKind};let hash=evidence_engine::sha256_hex(text.as_bytes());s.insert_item(&Item{id:id.into(),source_url:Some("https://private.example/token=secret".into()),source_type:SourceType::Text,title:Some("Private source title".into()),author:None,language:None,import_ts:100,content_hash:hash.clone(),extraction_confidence:0.9,status:ImportStatus::Ready,blocks:vec![Block{idx:0,kind:BlockKind::Paragraph,text:text.into()}]},text.as_bytes(),&hash).unwrap();}
#[test]fn sharing_preview_is_bound_to_source_and_private_context_never_leaks(){let mut a=Store::open_in_memory().unwrap();let b=Store::open_in_memory().unwrap();source(&mut a,"s","SECRET PREFIX approved quote SECRET SUFFIX");a.add_annotation("s","approved quote",Some("Private annotation not selected"),Some(0)).unwrap();let w=a.margin_create("Private first").unwrap();let mut input=NewEntry{workspace_id:w.id.clone(),kind:"highlight".into(),title:"Selected highlight".into(),local_item_id:Some("s".into()),block_idx:Some(0),quote:"approved quote".into(),..Default::default()};let preview=a.margin_preview(&input).unwrap();assert!(preview.anchor.as_ref().unwrap().prefix.is_empty());assert!(preview.source_url.is_none());input.review_hash=Store::margin_preview_hash(&preview).unwrap();a.conn.execute("UPDATE blocks SET text='CHANGED SECRET approved quote NEW SUFFIX' WHERE item_id='s'",[]).unwrap();assert!(a.margin_publish(&input).is_err());assert!(a.margin_view(&w.id).unwrap().entries.is_empty());let published=publish(&a,input).unwrap();let revision=&published.entries[0].versions[0];assert_eq!(published.entries[0].resolutions[&revision.id].status,"exact");a.margin_member(&w.id,&b.margin_contact().unwrap(),"viewer").unwrap();a.margin_enable(&w.id,true).unwrap();let packet=a.margin_export_packet(&ExportRequest{workspace_id:w.id.clone(),recipient:b.margin_contact().unwrap().data.signing_key,kind:"invite".into()}).unwrap();let inspect=json(&b.margin_inspect(&packet).unwrap()).unwrap();for private in["CHANGED SECRET","NEW SUFFIX","Private source title","token=secret","Private annotation not selected"]{assert!(!inspect.contains(private),"leaked {private}");}transfer(&a,&b,&w.id,"invite");assert_eq!(b.margin_view(&w.id).unwrap().entries[0].resolutions[&revision.id].status,"unbound");assert_eq!(a.list_annotations("s").unwrap()[0].note.as_deref(),Some("Private annotation not selected"));}
#[test]fn offline_state_identity_and_outgoing_retry_survive_reopen(){let dir=std::env::temp_dir().join(format!("refract-margins-{}",uuid::Uuid::new_v4()));std::fs::create_dir_all(&dir).unwrap();let path=dir.join("store.db");let a=Store::open(&path).unwrap();let b=Store::open_in_memory().unwrap();let key=a.margin_contact().unwrap().data.signing_key;let w=a.margin_create("Durable offline").unwrap();publish(&a,note(&w.id,"unsent but saved")).unwrap();a.margin_member(&w.id,&b.margin_contact().unwrap(),"editor").unwrap();a.margin_enable(&w.id,true).unwrap();let packet=a.margin_export_packet(&ExportRequest{workspace_id:w.id.clone(),recipient:b.margin_contact().unwrap().data.signing_key,kind:"invite".into()}).unwrap();let hash=evidence_engine::sha256_hex(packet.as_bytes());drop(a);let a=Store::open(&path).unwrap();assert_eq!(a.margin_contact().unwrap().data.signing_key,key);assert_eq!(a.margin_retry(&w.id,&hash).unwrap(),packet);assert_eq!(a.margin_view(&w.id).unwrap().entries[0].versions[0].body,"unsent but saved");drop(a);std::fs::remove_dir_all(dir).unwrap();}
#[test]fn v10_upgrade_preserves_legacy_private_workspaces_without_auto_sharing(){let mut s=Store::open_in_memory().unwrap();source(&mut s,"s","Private source");s.add_annotation("s","Private",Some("Private note"),Some(0)).unwrap();s.create_workspace("Legacy local only").unwrap();s.conn.execute_batch("DROP TABLE margin_history; DROP TABLE margin_transfers; DROP TABLE margin_bindings; DROP TABLE margin_contacts; DROP TABLE margin_workspaces; DROP TABLE margin_identity; UPDATE meta SET value='10' WHERE key='schema_version';").unwrap();s.migrate().unwrap();s.migrate().unwrap();assert!(s.margin_list().unwrap().is_empty());assert_eq!(s.list_workspaces().unwrap().len(),1);assert_eq!(s.list_annotations("s").unwrap()[0].note.as_deref(),Some("Private note"));}

#[test]fn malicious_timestamp_cannot_crash_mobile_date_rendering(){let s=Store::open_in_memory().unwrap();let ws=s.margin_create("Date bound").unwrap();let mut r=s.margin_preview(&note(&ws.id,"candidate")).unwrap();r.recorded_ts=i64::MAX;assert!(check_revision(&r).is_err());}

#[test]fn renumbered_blocks_cannot_be_mistaken_for_exact_anchor_identity(){use refract_core::{Block,BlockKind};let mut blocks=vec![Block{idx:0,kind:BlockKind::Heading1,text:"Heading".into()},Block{idx:1,kind:BlockKind::Paragraph,text:"FIRST selected quote first suffix".into()},Block{idx:2,kind:BlockKind::Paragraph,text:"SECOND selected quote second suffix".into()}];let a=annotation_engine::build_anchor(&blocks,1,"selected quote").unwrap();blocks[1].idx=10;blocks[2].idx=1;let(status,block)=annotation_engine::resolve_anchor(&a,&blocks);assert_eq!(status,annotation_engine::AnchorStatus::Relocated);assert_eq!(block,Some(10));}

#[test]fn v11_upgrade_supports_multiple_collaborator_aliases_for_one_local_original(){let mut s=Store::open_in_memory().unwrap();source(&mut s,"a","Same approved quote");source(&mut s,"b","Same approved quote");let w=s.margin_create("Aliases").unwrap();for item in["a","b"]{publish(&s,NewEntry{workspace_id:w.id.clone(),kind:"highlight".into(),title:"Selected".into(),local_item_id:Some(item.into()),block_idx:Some(0),quote:"approved quote".into(),..Default::default()}).unwrap();}let alias:String=s.conn.query_row("SELECT document_id FROM margin_bindings WHERE workspace_id=?1 AND item_id='b'",params![w.id],|r|r.get(0)).unwrap();s.conn.execute_batch("CREATE UNIQUE INDEX legacy_binding_item ON margin_bindings(workspace_id,item_id); UPDATE meta SET value='11' WHERE key='schema_version';").unwrap();s.migrate().unwrap();s.migrate().unwrap();let resolution=s.margin_bind(&w.id,&alias,"a").unwrap();assert_eq!(resolution.status,"exact");let count:i64=s.conn.query_row("SELECT COUNT(*) FROM margin_bindings WHERE workspace_id=?1 AND item_id='a'",params![w.id],|r|r.get(0)).unwrap();assert_eq!(count,2);assert!(s.get_item("b").unwrap().is_some());}
